const RANK_KEY='chiikawa-ranking-v1';let runStats={coins:0,stars:0,rainbows:0,coinPoints:0,maxCombo:0},pendingRank=null;
function loadRanks(){try{const a=JSON.parse(localStorage.getItem(RANK_KEY)||'[]');return Array.isArray(a)?a.filter(r=>typeof r.name==='string'&&Number.isFinite(r.score)&&r.score>=0&&Number.isFinite(r.seconds)).slice(0,100):[]}catch{return []}}
function sortedRanks(rows){return [...rows].sort((a,b)=>b.score-a.score||Number(b.clear)-Number(a.clear)||b.seconds-a.seconds||a.date-b.date).slice(0,10)}
const rankBegin=begin,rankCollect=collect,rankResult=result;
begin=function(){const form=$('rank-form');if(form)form.remove();pendingRank=null;runStats={coins:0,stars:0,rainbows:0,coinPoints:0,maxCombo:0};rankBegin()};
collect=function(c){const taken=c.taken,previous=score;rankCollect(c);if(!taken&&c.taken&&['normal','star','special'].includes(c.type)){runStats[c.type==='normal'?'coins':c.type==='star'?'stars':'rainbows']++;runStats.coinPoints+=score-previous;runStats.maxCombo=Math.max(runStats.maxCombo,combo)}};
result=function(clear){rankResult(clear);pendingRank={score,clear,seconds:Math.min(120,time),stage:chapterIndex()+1,combo:runStats.maxCombo,date:Date.now()};const form=document.createElement('form');form.id='rank-form';form.innerHTML='<div class="score-detail"></div><div class="rank-entry"><input name="nickname" aria-label="랭킹 닉네임" maxlength="12" placeholder="닉네임 (최대 12자)" required><button class="rank-save" type="submit">기록 등록</button></div><div class="rank-feedback" role="status"></div>';
form.querySelector('.score-detail').textContent=`코인 ${runStats.coins}개 · 별 ${runStats.stars}개 · 무지개 ${runStats.rainbows}개 | 최고 ${runStats.maxCombo}콤보\n코인 점수 ${runStats.coinPoints.toLocaleString()} + 돌파 보너스 ${(score-runStats.coinPoints).toLocaleString()}`;
const input=form.elements.nickname;input.addEventListener('input',()=>input.setCustomValidity(''));try{input.value=localStorage.getItem('chiikawa-nickname')||''}catch{}form.addEventListener('keydown',e=>e.stopPropagation());input.addEventListener('pointerdown',e=>e.stopPropagation());form.onsubmit=e=>{e.preventDefault();e.stopPropagation();if(!pendingRank)return;const name=input.value.trim().slice(0,12);if(!name){input.setCustomValidity('닉네임을 입력해 주세요.');input.reportValidity();return}input.setCustomValidity('');const record={...pendingRank,name};const rows=sortedRanks([...loadRanks(),record]);try{localStorage.setItem(RANK_KEY,JSON.stringify(rows));localStorage.setItem('chiikawa-nickname',name)}catch{form.querySelector('.rank-feedback').textContent='저장 공간에 접근할 수 없어 기록을 저장하지 못했어요.';return}pendingRank=null;form.querySelector('button').disabled=true;input.disabled=true;const position=rows.findIndex(r=>r.date===record.date&&r.name===name);form.querySelector('.rank-feedback').textContent=position>=0?`내 랭킹 ${position+1}위에 등록했어요!`:'기록을 확인했어요. TOP 10에 다시 도전해 보세요!';renderRanks();};$('message').after(form)};
function renderRanks(){const body=$('ranking-body');body.replaceChildren();const rows=sortedRanks(loadRanks());if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.textContent='첫 모험을 마치고 랭킹에 이름을 남겨보세요!';tr.append(td);body.append(tr);return}rows.forEach((r,i)=>{const tr=document.createElement('tr');[i<3?['🥇','🥈','🥉'][i]:String(i+1),r.name,r.score.toLocaleString()+'점',r.clear?'축제 도착 ✨':`${r.stage} 스테이지`,`${Math.floor(r.seconds)}초 · ${r.combo||0}콤보`].forEach(value=>{const td=document.createElement('td');td.textContent=value;tr.append(td)});body.append(tr)})}
renderRanks();
